using System.Text.Json.Serialization;
using Perigon.Core.Models;
using Perigon.Models.Enums;

namespace Perigon.Models;

/// <summary>
/// Citation settings for newsletters generated by the monitor.
/// </summary>
public record SignalMonitoringPlanNewsletterConfig
{
    /// <summary>
    /// Whether generated newsletters include citations. Defaults to true.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("citations")]
    public bool? Citations { get; init; }

    /// <summary>
    /// How story citations are resolved. Accepts STORY or TOP_ARTICLE.
    /// </summary>
    [JsonPropertyName("storyCitationResolvingType")]
    public required StoryCitationResolvingType StoryCitationResolvingType { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
